styles:
.rog-post-container {
            width: 100%;
            max-width: 100%;
        }
        .rog-post-container img {
            max-width: 100% !important;
            height: auto !important;
            display: block;
            margin: 25px auto;
            border-radius: 4px;
        }
        .rog-post-container a {
            color: #ff3333 !important;
            text-decoration: none;
            font-weight: bold;
        }
        .rog-post-container a:hover {
            text-decoration: underline;
            color: #ff0000 !important;
        }
        .rog-post-container h2 {
            color: #ffffff !important;
            border-left: 5px solid #cc0000;
            padding-left: 15px;
            margin-top: 40px;
            margin-bottom: 20px;
            text-transform: uppercase;
            font-weight: 700;
            font-size: 1.8em;
        }
        .rog-post-container p {
            color: #ffffff !important;
            margin-bottom: 20px;
        }
        /* Style cho Bảng */
        .rog-post-container table {
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
            background-color: #1a1a1a;
            color: #ffffff;
            font-size: 0.95em;
        }
        .rog-post-container th, .rog-post-container td {
            border: 1px solid #333;
            padding: 12px;
            text-align: left;
        }
        .rog-post-container th {
            background-color: #330000;
            text-transform: uppercase;
            font-weight: bold;
            text-align: center;
        }
        .rog-post-container td {
            vertical-align: top;
        }
